        dtFillRepeat(src, 100000, 7, 7, 7);
        int zn = dtCompress(ws, z, src, 100000, 3);
        emon.Testport.assertThat(zn < 200, "100,000 equal bytes in a few dozen bytes");
        emon.Testport.assertEq(dtVerify(z, src, 100000, dec, st), -1, "round trip");
        emon.Testport.assertEq(dtTrip(src, 100000, 0), -1, "by cost");
