    public static void testAMatchAtDistance32768IsUsed() {
        // Ten rare bytes, 32,758 bytes that never contain byte 1, the ten again:
        // the only way to code the last ten cheaply is distance 32,768. Against
        // the same data with the last byte changed, the stream is shorter.
        emon.Port.Cells src = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Buf z = emon.Port.newBuf();
        emon.Port.Cells dec = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        emon.Port.Cells rnd = emon.Port.newCells();
        int i = 0;
        int zn1 = 0;
        Splitmix.smSeed(rnd, 21);
        while (i < 10) {
            emon.Port.cellsPush(src, 1 + i);
            i += 1;
        }
        while (i < 32768) {
            emon.Port.cellsPush(src, 20 + Splitmix.smBelow(rnd, 200));
            i += 1;
        }
        i = 0;
        while (i < 10) {
            emon.Port.cellsPush(src, 1 + i);
            i += 1;
        }
        emon.Testport.assertEq(emon.Port.cellsLen(src), 32778, "length");
        zn1 = dtCompress(ws, z, src, 32778, 2);
        emon.Testport.assertEq(dtVerify(z, src, 32778, dec, st), -1, "round trip");
        emon.Port.cellsSet(src, 32777, 99);
        int zn2 = dtCompress(ws, z, src, 32778, 2);
        emon.Testport.assertThat((zn2 - zn1) > 0, "a changed last byte costs more bytes");
        emon.Testport.assertEq(dtVerify(z, src, 32778, dec, st), -1, "round trip, changed");
    }
